    24→struct LoadableImage<TransformerView: View, PlaceholderView: View>: View {
    25→    private let mediaSource: MediaSourceProxy?
    26→    private let mediaType: LoadableImageMediaType
    27→    private let blurhash: String?
    28→    private let size: CGSize?
    29→    private let mediaProvider: MediaProviderProtocol?
    30→    private let transformer: (AnyView) -> TransformerView
    31→    private let placeholder: () -> PlaceholderView
    32→    
    33→    /// A SwiftUI view that automatically fetches images
    34→    /// It will try fetching the image from in-memory cache and if that's not available
    35→    /// it will fire a task to load it through the image provider
    36→    /// - Parameters:
    37→    ///   - mediaSource: the source of the image
    38→    ///   - blurhash: an optional blurhash
    39→    ///   - transformer: entry point for configuring the resulting image view
    40→    ///   - placeholder: a view to show while the image or blurhash are not available
    41→    init(mediaSource: MediaSourceProxy,
    42→         mediaType: LoadableImageMediaType = .generic,
    43→         blurhash: String? = nil,
    44→         size: CGSize? = nil,
    45→         mediaProvider: MediaProviderProtocol?,
    46→         transformer: @escaping (AnyView) -> TransformerView = { $0 },
    47→         placeholder: @escaping () -> PlaceholderView) {
    48→        self.mediaSource = mediaSource
    49→        self.mediaType = mediaType
    50→        self.blurhash = blurhash
    51→        self.size = size
    52→        self.mediaProvider = mediaProvider
    53→        self.transformer = transformer
    54→        self.placeholder = placeholder
    55→    }
    56→    
    57→    init(url: URL,
    58→         mediaType: LoadableImageMediaType = .generic,
    59→         blurhash: String? = nil,
    60→         size: CGSize? = nil,
    61→         mediaProvider: MediaProviderProtocol?,
    62→         transformer: @escaping (AnyView) -> TransformerView = { $0 },
    63→         placeholder: @escaping () -> PlaceholderView) {
    64→        mediaSource = try? MediaSourceProxy(url: url, mimeType: nil)
    65→        self.mediaType = mediaType
    66→        self.blurhash = blurhash
    67→        self.size = size
    68→        self.mediaProvider = mediaProvider
    69→        self.transformer = transformer
    70→        self.placeholder = placeholder
    71→    }
    72→    
    73→    var body: some View {
    74→        if let mediaSource {
    75→            LoadableImageContent(mediaSource: mediaSource,
    76→                                 mediaType: mediaType,
    77→                                 blurhash: blurhash,
    78→                                 size: size,
    79→                                 mediaProvider: mediaProvider,
    80→                                 transformer: transformer,
    81→                                 placeholder: placeholder)
    82→                .id(stableMediaIdentifier)
    83→        } else {
    84→            placeholder()
    85→        }
    86→    }
    87→    
    88→    private var stableMediaIdentifier: String? {
    89→        switch mediaType {
    90→        case .timelineItem(let uniqueID):
    91→            // Consider media for the same item to be the same view
    92→            uniqueID.value
    93→        default:
    94→            // Binds the lifecycle of the LoadableImage to the associated URL.
    95→            // This fixes the problem of the cache returning old values after a change in the URL.
    96→            mediaSource?.url.absoluteString
    97→        }
    98→    }
    99→}
