   246→private class ContentLoader: ObservableObject {
   247→    enum Content: Equatable {
   248→        case image(UIImage)
   249→        case gifData(Data)
   250→    }
   251→    
   252→    private let mediaProvider: MediaProviderProtocol?
   253→    private let mediaSource: MediaSourceProxy
   254→    private let size: CGSize?
   255→    private var imageLoadingCancellable: AnyCancellable?
   256→    
   257→    @Published private var cachedContent: Content?
   258→    
   259→    var content: Content? {
   260→        if cachedContent != nil {
   261→            return cachedContent
   262→        }
   263→        
   264→        if isGIF {
   265→            if let image = mediaProvider?.imageFromSource(mediaSource),
   266→               let data = image.kf.data(format: .GIF) {
   267→                return .gifData(data)
   268→            }
   269→        } else if let image = mediaProvider?.imageFromSource(mediaSource, size: size) {
   270→            return .image(image)
   271→        }
   272→        
   273→        return cachedContent
   274→    }
   275→    
   276→    init(mediaSource: MediaSourceProxy, size: CGSize?, mediaProvider: MediaProviderProtocol?) {
   277→        self.mediaSource = mediaSource
   278→        self.size = size
   279→        self.mediaProvider = mediaProvider
   280→    }
